def enc_boxs(EB, imp, R, X, sn, m, cache, ri):
    """(i) for a container with one byte-vector storage field (MatrixEntry): rep's witnesses, the storage
    at the encoder's depth (hc, as the word-storage family), its length from rep's ByteVector fact"""
    f = ri['rt']['file']
    ee, es = m['encode_eval'][0], m['encode_spec'][0]
    b_ee = EB.law(cache, ee)
    mt = re.match(r'\{F\.emitted\(T\.(\w+), T\.\1_encode\((.*)\), (\d+)\) == \(\2, (.*)\) : T\.\1 & \+List<U32>\}$', b_ee[3])
    if not mt:
        return None
    OBJ = imp.qual(EB, mt.group(2), ee['file'])
    NW, BY = mt.group(3), imp.qual(EB, mt.group(4), ee['file'])
    rb = Rebuild(EB, imp, f)
    W, E = rb.run(f'rep_{X}', 'o', 'rep', f'Spec.{sn}()')
    cw, co = split_args(W), split_args(OBJ)
    si = [k for k, a in enumerate(cw[1]) if a.startswith('O.Words{')]
    if len(si) != 1:
        return None
    si = si[0]
    mw = re.match(r'O\.Words\{FD\.array__thaw\(U32, (\w+)\), (\w+)\}$', cw[1][si])
    mo = re.match(r'O\.Words\{(.*), (\d+)\}$', co[1][si], re.S)
    wt, wN = mw.groups()
    tree, NL = mo.group(1), mo.group(2)
    leaves = re.findall(r'ALeaf\{(\w+)\}', tree)
    d = len(leaves).bit_length() - 1
    wmap = {}
    for k, (a, b) in enumerate(zip(cw[1], co[1])):
        if k != si and not align(a, b, wmap):
            return None
    others = [x for x, _ in rb.wits if x in wmap]
    # the storage field's pj term, and rep's facts about it
    pj = f'{imp.alias("proofs/obj/" + f)}.pj_{X}_{si}(o)'
    cf = [(v, t) for v, t in rb.facts if ('ByteVector_length' in t or 'chunks_of' in t) and pj in t]
    if len(cf) != 1:
        return None
    cfv, cft = cf[0]
    pvk = 'chunks_of' in cft
    if pvk:
        ens = [(v, t) for v, t in rb.facts if re.match(r'\{U32\.to_nat\(' + wN + r'\) == Nat\.add\([\w.]+\.e32\((\w+)\), 32n\) : Nat\}$', t)]
        if len(ens) != 1:
            return None
        env_, ent = ens[0]
        wq = re.search(r'e32\((\w+)\)', ent).group(1)
        e32 = re.search(r'([\w.]+\.e32)\(', ent).group(1)
    LT = {x: EB.leafterm(i, d) for i, x in enumerate(leaves)}
    xs = [pmode(q)[1] for q in b_ee[2]]
    AE, AS = imp.alias('proofs/obj/' + ee['file']), imp.alias('proofs/obj/' + es['file'])
    ot = f'T.{X}'
    V = lambda o: sub_o(subst_s(imp.qual(EB, ri['view'], f), sn), o)  # noqa: E731
    REP = lambda o: f'{imp.alias("proofs/obj/" + f)}.rep_{X}({o}, Spec.{sn}())'  # noqa: E731
    Gb = lambda o, vv: f'{{Some{{E.obytes(Pair.snd({ot}, B.Buf, T.{X}_encode({o})))}} == API.serialize(Spec.{sn}(), {vv}) : {MB}}}'  # noqa: E731
    Wf = lambda t_, n_: W.replace(cw[1][si], f'O.Words{{FD.array__thaw(U32, {t_}), {n_}}}')  # noqa: E731
    def WfP(t_):
        o_ = Wf(t_, NL)
        for x in others:
            o_ = re.sub(r'(?<![\w.])' + x + r'(?![\w{])', wmap[x], o_)
        return o_
    OBJt = WfP(f'E3.tf({d}n, t)')
    SVt = imp.qual(EB, EB.call_args(EB.law(cache, es)[3], 'Decoding.decodes')[2], es['file'])
    amap_ = {**LT}
    eargs = ', '.join(amap_.get(x, x) for x in xs)
    SV = subv(SVt, LT)
    HC = lambda o: f'{{E3.at_depth({o}, {d}n) == True{{}} : Bool}}'  # noqa: E731
    witp = ', '.join(f'+{x}: {t}' for x, t in rb.wits if x in others)
    wita = ', '.join(others)
    pats = [re.sub(r'(?<![\w.])(' + '|'.join(map(re.escape, xs)) + r')(?![\w{(])', r'+\1', wmap[w]) for w in others]
    L = [f'# {R} ({X})',
         f'def {R}_w3(+t: FD.array__Tree<U32>, +pf: {{FD.array__perfect(U32, {d}n, t) == True{{}} : Bool}}, {witp}) -> {Gb(Wf("t", NL), V(Wf("t", NL)))}:',
         f'  match {" ".join(others)}:', f'    case {" ".join(pats)}:',
         f'      %Equal.sym(FD.array__Tree<U32>, t, E3.tf({d}n, t), E3.eta({d}n, t, pf)) : {Gb(WfP("_"), V(WfP("_")))}',
         f'      Equal.trans({MB}, Some{{E.obytes(Pair.snd({ot}, B.Buf, T.{X}_encode({OBJt})))}}, Some{{{subv(BY, LT)}}}, API.serialize(Spec.{sn}(), {V(OBJt)}),',
         f'        Equal.cong({ot} & +List<U32>, {MB}, p => Some{{Pair.snd({ot}, +List<U32>, p)}}, F.emitted({ot}, T.{X}_encode({OBJt}), {NW}), ({OBJt}, {subv(BY, LT)}), {AE}.{ee["law"]}({eargs})),',
         f'        Equal.sym({MB}, API.serialize(Spec.{sn}(), {V(OBJt)}), Some{{{subv(BY, LT)}}},',
         f'          Equal.trans({MB}, API.serialize(Spec.{sn}(), {V(OBJt)}), Encoding.encoding_for_legal_type(Spec.{sn}(), {V(OBJt)}), Some{{{subv(BY, LT)}}},',
         f'            E.serialize_legal(Spec.{sn}(), {V(OBJt)}, VS.public_sound(Spec.{sn}(), {{==}})), {AS}.{es["law"]}({", ".join(LT.get(x, x) for x in [pmode(q)[1] for q in EB.law(cache, es)[2]])}))))', '']
    ON = 'O.Words{FD.array__thaw(U32, t), N}'
    cfW = cft.replace(pj, ON)
    if pvk:
        VLt = re.search(r'([\w.]+\.Vector_length\(.*\))\) == True', cfW).group(1)
        PVa = imp.alias('proofs/obj/pv_obj.bend')
        qlit = int(NL) // 32 - 1
        extra = f', +q: Nat, +en: {{U32.to_nat(N) == Nat.add({e32}(q), 32n) : Nat}}'
        lnl = [f'  +kq = {PVa}.k_len({ON}, t, N, q, {VLt}, {{==}}, en, cf)',
               f'  +eq_ = FD.nat__succ_inj(q, {qlit}n, Equal.sym(Nat, {VLt}, 1n+q, kq))',
               f'  +ln = Equal.trans(Nat, U32.to_nat(N), Nat.add({e32}(q), 32n), U32.to_nat({NL}), en, Equal.cong(Nat, Nat, z => Nat.add({e32}(z), 32n), q, {qlit}n, eq_))']
        w2call_extra = f', {wq}, {env_}'
    else:
        extra = ''
        lnl = [f'  +ln = Equal.trans(Nat, U32.to_nat(N), {re.search(r"(SH\.ByteVector_length\(.*\))\) == True", cfW).group(1)}, U32.to_nat({NL}), FD.nat__eq_from_is_eq(U32.to_nat(WO.len({ON})), {re.search(r"(SH\.ByteVector_length\(.*\))\) == True", cfW).group(1)}, cf), {{==}})']
        w2call_extra = ''
    L += [f'def {R}_w2(+t: FD.array__Tree<U32>, +N: U32, {witp}, +cf: {cfW}, +hc: {HC(ON)}{extra}) -> {Gb(Wf("t", "N"), V(Wf("t", "N")))}:'] + lnl + [
          f'  +eN = FD.u32__injective(N, {NL}, ln)',
          f'  +pf = FD.logic__subst(FD.array__Tree<U32>, z => {{FD.array__perfect(U32, {d}n, z) == True{{}} : Bool}}, FD.array__freeze(U32, FD.array__thaw(U32, t)), t, FD.array__freeze_thaw(U32, t), hc)',
          f'  %Equal.sym(U32, N, {NL}, eN) : {Gb(Wf("t", "_"), V(Wf("t", "_")))}',
          f'  {R}_w3(t, pf, {wita})', '']
    pjW = lambda z: pj.replace('(o)', f'({z})')  # noqa: E731
    cfz = cft.replace(pj, pjW('z'))
    L += [f'# (i) under rep (the root law\'s invariant) with the storage field at the encoder\'s depth {d} (hc).',
          f'def {R}_e2e_encode(-o: {ot}, +rep: {REP("o")}, +hc: {HC(pj)}) -> {Gb("o", V("o"))}:'] + ['  ' + l for l in rb.lines] + [
          f'  +eq = {E}',
          f'  +cf = FD.logic__subst({ot}, z => {cfz}, o, {W}, eq, {cfv})',
          f'  +hc2 = FD.logic__subst({ot}, z => {HC(pjW("z"))}, o, {W}, eq, hc)',
          f'  %X.sym_e({ot}, o, {W}, eq) : {Gb("_", V("_"))}',
          f'  {R}_w2({wt}, {wN}, {wita}, cf, hc2{w2call_extra})', '']
    return '\n'.join(L)


