def pbs_split_top(s):
    out, d, cur = [], 0, ''
    for ch in s:
        if ch in '({[':
            d += 1
        elif ch in ')}]':
            d -= 1
        if ch == ',' and d == 0:
            out.append(cur.strip())
            cur = ''
        else:
            cur += ch
    out.append(cur.strip())
    return out


def pbs_conj(s):
    """Bool.and(a, Bool.and(b, c)) -> [a, b, c]"""
    s = s.strip()
    if s.startswith('Bool.and(') and s.endswith(')'):
        a, b = pbs_split_top(s[len('Bool.and('):-1])
        return [a] + pbs_conj(b)
    return [s]


def pbs_AND(cs):
    return cs[0] if len(cs) == 1 else f'Bool.and({cs[0]}, {pbs_AND(cs[1:])})'


def pbs_and_intro(cs, ps):
    if len(cs) == 1:
        return ps[0]
    return f'FD.logic__and_intro({cs[0]}, {pbs_AND(cs[1:])}, {ps[0]},\n    {pbs_and_intro(cs[1:], ps[1:])})'


def pbs_okt(path, params, vals):
    src = open(str(PBS_ROOT) + '/' + path).read()
    m = re.search(r'^def OKT\((.*?)\) -> Bool:(?:\n  | )(.*)$', src, re.M)
    body = m.group(2)
    for p, v in zip(params, vals):
        body = re.sub(r'(?<![\w.])' + p + r'(?![\w])', lambda _: v, body)
    return pbs_conj(body)


def pbs_wpat(p, plus=True):
    s = 'WNil{}'
    for i in reversed(range(32)):
        s = f'WCon{{{"+" if plus else ""}{p}{i}, {s}}}'
    return f'U32{{{s}}}'


